// Generate TypeScript types from the JSON Schemas that `cargo xtask schemas`
// writes from the Rust types (web/schemas): the Rust types are the single
// source; never edit src/generated by hand.
//
// The schemas of a group (jobs, types) are merged into one, so a Rust type
// shared by several documents gives one TypeScript type.
import { mkdir, readdir, readFile, writeFile } from "node:fs/promises";
import { basename, join } from "node:path";
import { isDeepStrictEqual } from "node:util";
import { compile } from "json-schema-to-typescript";

const root = new URL("..", import.meta.url).pathname;
const schemas = join(root, "schemas");
const out = join(root, "src", "generated");

const pascal = (name) =>
  name
    .split(/[-_]/)
    .map((w) => w.charAt(0).toUpperCase() + w.slice(1))
    .join("");

// A `$ref` with sibling annotations (a description) would make a copy of
// the referenced type: drop the annotations. Structural siblings (the tag
// property of an internally tagged variant) are kept through `allOf`.
const ANNOTATIONS = new Set([
  "description",
  "title",
  "default",
  "examples",
  "deprecated",
  "readOnly",
  "writeOnly",
]);
function bareRefs(value) {
  if (Array.isArray(value)) return value.map(bareRefs);
  if (value === null || typeof value !== "object") return value;
  if (typeof value.$ref === "string") {
    const structural = Object.fromEntries(
      Object.entries(value).filter(
        ([k]) => k !== "$ref" && !ANNOTATIONS.has(k) && !k.startsWith("x-"),
      ),
    );
    if (Object.keys(structural).length === 0) return { $ref: value.$ref };
    return { allOf: [{ $ref: value.$ref }, bareRefs(structural)] };
  }
  return Object.fromEntries(Object.entries(value).map(([k, v]) => [k, bareRefs(v)]));
}

async function merged(dir, suffix) {
  const files = (await readdir(join(schemas, dir))).filter((f) => f.endsWith(".json")).sort();
  const defs = {};
  const names = [];
  const add = (name, schema, file) => {
    if (defs[name] !== undefined && !isDeepStrictEqual(defs[name], schema)) {
      throw new Error(`${file}: type ${name} differs from another schema's`);
    }
    defs[name] = schema;
  };
  for (const file of files) {
    const schema = bareRefs(JSON.parse(await readFile(join(schemas, dir, file), "utf8")));
    const { $defs = {}, $schema: _, title: __, ...top } = schema;
    for (const [name, def] of Object.entries($defs)) add(name, def, file);
    const name = pascal(basename(file, ".json")) + suffix;
    add(name, top, file);
    names.push([basename(file, ".json"), name]);
  }
  const combined = {
    title: `${pascal(dir)}Root`,
    type: "object",
    additionalProperties: false,
    properties: Object.fromEntries(names.map(([, n]) => [n, { $ref: `#/$defs/${n}` }])),
    $defs: Object.fromEntries(Object.entries(defs).map(([n, d]) => [n, { ...d, title: n }])),
  };
  const text = await compile(combined, `${pascal(dir)}Root`, {
    bannerComment: "",
    additionalProperties: false,
    declareExternallyReferenced: true,
    unreachableDefinitions: true,
    style: { semi: true },
  });
  return { text, names };
}

await mkdir(out, { recursive: true });
const banner = "// Generated by scripts/gen-types.mjs from web/schemas: do not edit.\n\n";
const jobs = await merged("jobs", "Job");
const types = await merged("types", "");
await writeFile(
  join(out, "jobs.ts"),
  `${banner}export namespace Jobs {\n${jobs.text}}\n\n` +
    `/** Analysis names, in the order of the registry files. */\n` +
    `export const ANALYSES = ${JSON.stringify(jobs.names.map(([n]) => n))} as const;\n`,
);
await writeFile(join(out, "types.ts"), `${banner}export namespace Api {\n${types.text}}\n`);
console.log(`types: ${jobs.names.length} jobs, ${types.names.length} documents`);
